report={'binary_sha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'compiler':'/tmp/semantic-review-native/bend/bin/bend','cases':[]}
for kind in ['definition-rename','expression-constructor-exact-issue','expression-constructor-with-base']:
 with tempfile.TemporaryDirectory(prefix='review-p1-'+kind+'-') as temporary:
  workspace=Path(temporary);root=workspace/'main.bend';uri=root.as_uri()
  text=('import Base\ndef wrap(target: U32) -> U32:\n  target\ndef Foo.target() -> U32:\n  1\ndef main() -> U32:\n  Foo.target()\n' if kind=='definition-rename' else ('type Shape is Data:\n  Pair{value: U32}\ndef make() -> Shape:\n  Pa\n' if kind=='expression-constructor-exact-issue' else 'import Base\ntype Shape is Data:\n  CustomPair{value: U32}\ndef make() -> Shape:\n  CustomPa\n'))
  root.write_text(text);case={'kind':kind,'initial_source':text};client=Trace(binary,workspace)
  try:
   client.compiler_path=report['compiler'];client.settings={'bend2-lsp':{'compilerPath':client.compiler_path,'compilerArguments':[]}}
   client.initialize();client.notify('textDocument/didOpen',{'textDocument':{'uri':uri,'languageId':'bend','version':1,'text':text}})
   if kind=='definition-rename':
    case['parameter_definition']=client.request('textDocument/definition',{'textDocument':{'uri':uri},'position':{'line':2,'character':4}})[0]
    assert case['parameter_definition']=={'uri':uri,'range':{'start':{'line':1,'character':9},'end':{'line':1,'character':15}}},case
    case['invalid_rename']=client.expected_error('textDocument/rename',{'textDocument':{'uri':uri},'position':{'line':6,'character':8},'newName':'bad name'})
    assert case['invalid_rename']['error']['code']==-32602 and 'result' not in case['invalid_rename'],case
    version=1
    for label,position,new_name in [('local-dotted',{'line':2,'character':4},'new.atom'),('global-keyword-terminal',{'line':6,'character':8},'def'),('global-underscore-terminal',{'line':6,'character':7},'_')]:
     edit=client.request('textDocument/rename',{'textDocument':{'uri':uri},'position':position,'newName':new_name})[0]
     assert len(workspace_edits(edit,uri,version))==2,edit
     text=apply_edit(text,edit,uri,version);version+=1
     client.notify('textDocument/didChange',{'textDocument':{'uri':uri,'version':version},'contentChanges':[{'text':text}]})
     case[label]={'edit':edit,'source':text,'diagnostics':client.current_diagnostics(uri,version)}
     assert case[label]['diagnostics']['diagnostics']==[],case[label]
    case['final_parameter_definition']=client.request('textDocument/definition',{'textDocument':{'uri':uri},'position':{'line':2,'character':6}})[0]
    assert case['final_parameter_definition']=={'uri':uri,'range':{'start':{'line':1,'character':9},'end':{'line':1,'character':17}}},case
    case['final_global_definition']=client.request('textDocument/definition',{'textDocument':{'uri':uri},'position':{'line':6,'character':6}})[0]
    assert case['final_global_definition']=={'uri':uri,'range':{'start':{'line':3,'character':4},'end':{'line':3,'character':9}}},case
   else:
    exact=kind=='expression-constructor-exact-issue';label='Pair' if exact else 'CustomPair';prefix='Pa' if exact else 'CustomPa';body_line=3 if exact else 4
    completion=client.request('textDocument/completion',{'textDocument':{'uri':uri},'position':{'line':body_line,'character':2+len(prefix)}})[0]
    items=completion if isinstance(completion,list) else completion['items'];pairs=[item for item in items if item['label']==label]
    assert len(pairs)==1 and pairs[0]['kind']==4,pairs
    expected_range={'start':{'line':body_line,'character':2},'end':{'line':body_line,'character':2+len(prefix)}}
    assert pairs[0]['textEdit']=={'newText':label,'range':expected_range},pairs
    case['pair_completion']=pairs[0];case['unfinished_input_diagnostics']=client.current_diagnostics(uri,1)
    assert any(d['code']=='compiler' and d['severity']==1 for d in case['unfinished_input_diagnostics']['diagnostics']),case
    if not exact:
     start=offset(text,expected_range['start']);end=offset(text,expected_range['end']);text=text[:start]+label+'{1}'+text[end:]
     client.notify('textDocument/didChange',{'textDocument':{'uri':uri,'version':2},'contentChanges':[{'text':text}]})
     case['manually_completed_constructor_call']={'source':text,'diagnostics':client.current_diagnostics(uri,2)}
     assert case['manually_completed_constructor_call']['diagnostics']['diagnostics']==[],case
   client.finish();case['exit']=client.process.returncode
   if kind!='expression-constructor-exact-issue':
    root.write_text(text)
    checked=subprocess.run([report['compiler'],str(root)],capture_output=True,text=True,timeout=30)
    case['direct_genuine_compiler_check']={'returncode':checked.returncode,'stdout':checked.stdout,'stderr':checked.stderr}
    assert checked.returncode==0,case
  except BaseException:
   case['raw_messages']=client.raw;case['stderr']=client.stderr_tail();print(json.dumps({'completed':report,'failed':case},ensure_ascii=False,indent=2),file=sys.stderr);raise
  finally:case['raw_messages']=client.raw;case['stderr']=client.stderr_tail();client.close()
  report['cases'].append(case)
print(json.dumps(report,ensure_ascii=False,indent=2))

